3	import type * as Plotly from "plotly.js";
4	import { z } from "zod";
5	import type { IPlugin, IPluginProps, Setter } from "@/plugins/types";
6	import { Logger } from "@/utils/Logger";
7	import type { Figure } from "./Plot";
8	
9	import "./plotly.css";
10	import "./mapbox.css";
11	import { set } from "lodash-es";
12	import { type JSX, lazy, memo, useMemo } from "react";
13	import useEvent from "react-use-event-hook";
14	import { useDeepCompareMemoize } from "@/hooks/useDeepCompareMemoize";
15	import { useScript } from "@/hooks/useScript";
16	import { Arrays } from "@/utils/arrays";
17	import { Objects } from "@/utils/objects";
18	import {
19	  extractClickSelection,
20	  extractIndices,
21	  extractPoints,
22	} from "./selection";
23	import { usePlotlyLayout } from "./usePlotlyLayout";
24	
25	interface Data {
26	  figure: Figure;
27	  config: Partial<Plotly.Config>;
28	}
29	
30	type T =
31	  | {
32	      points?: Record<string, unknown>[] | Plotly.PlotDatum[];
33	      indices?: number[];
34	      range?: {
35	        x?: number[];
36	        y?: number[];
37	      };
38	      // These are kept in the state to persist selections across re-renders
39	      // on the frontend, but likely not used in the backend.
40	      selections?: unknown[];
41	      dragmode?: Plotly.Layout["dragmode"];
42	      xaxis?: Partial<Plotly.LayoutAxis>;
43	      yaxis?: Partial<Plotly.LayoutAxis>;
44	    }
45	  | undefined;
46	
47	export class PlotlyPlugin implements IPlugin<T, Data> {
48	  tagName = "marimo-plotly";
49	
50	  validator = z.object({
51	    figure: z
52	      .object({})
53	      .passthrough()
54	      .transform((spec) => spec as unknown as Figure),
55	    config: z.object({}).passthrough(),
56	  });
57	
58	  render(props: IPluginProps<T, Data>): JSX.Element {
59	    return (
60	      <PlotlyComponent
61	        {...props.data}
62	        host={props.host}
63	        value={props.value}
64	        setValue={props.setValue}
65	      />
66	    );
67	  }
68	}
69	
70	interface PlotlyPluginProps extends Data {
71	  value: T;
72	  setValue: Setter<T>;
73	  host: HTMLElement;
74	}
75	
76	const LazyPlot = lazy(() =>
77	  import("./Plot").then((mod) => ({ default: mod.Plot })),
78	);
79	
80	const SUNBURST_DATA_KEYS: (keyof Plotly.SunburstPlotDatum)[] = [
81	  "color",
82	  "curveNumber",
83	  "entry",
84	  "hovertext",
85	  "id",
86	  "label",
87	  "parent",
88	  "percentEntry",
89	  "percentParent",
90	  "percentRoot",
91	  "pointNumber",
92	  "root",
93	  "value",
94	] as const;
95	const TREE_MAP_DATA_KEYS = SUNBURST_DATA_KEYS;
96	
97	export const PlotlyComponent = memo(
98	  ({ figure: originalFigure, value, setValue, config }: PlotlyPluginProps) => {
99	    // Used for rendering LaTeX. TODO: Serve this library from Marimo
100	    const scriptStatus = useScript(
101	      "https://cdn.jsdelivr.net/npm/mathjax-full@3.2.2/es5/tex-mml-svg.min.js",
102	    );
103	    const isScriptLoaded = scriptStatus === "ready";
104	
105	    const { figure, layout, handleReset } = usePlotlyLayout({
106	      originalFigure,
107	      initialValue: value,
108	      isScriptLoaded,
109	    });
110	
111	    const handleResetWithClear = useEvent(() => {
112	      handleReset();
113	      setValue({});
114	    });
115	
116	    const configMemo = useDeepCompareMemoize(config);
117	    const plotlyConfig = useMemo((): Partial<Plotly.Config> => {
118	      return {
119	        displaylogo: false,
120	        modeBarButtonsToAdd: [
121	          // Custom button to reset the state
122	          {
123	            name: "reset",
124	            title: "Reset state",
125	            icon: {
126	              svg: `
127	              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor"
128	                stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-rotate-ccw">
129	                <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" />
130	                <path d="M3 3v5h5" />
131	              </svg>`,
132	            },
133	            click: handleResetWithClear,
134	          },
135	        ],
136	        // Prioritize user's config
137	        ...configMemo,
138	      };
139	    }, [handleResetWithClear, configMemo]);
140	
141	    return (
142	      <LazyPlot
143	        {...figure}
144	        layout={layout}
145	        onRelayout={(layoutUpdate) => {
146	          // Persist dragmode in the state to keep it across re-renders
147	          if ("dragmode" in layoutUpdate) {
148	            setValue((prev) => ({ ...prev, dragmode: layoutUpdate.dragmode }));
149	          }
150	
151	          // Persist xaxis/yaxis changes in the state to keep it across re-renders
152	          if (
153	            Object.keys(layoutUpdate).some(
154	              (key) => key.includes("xaxis") || key.includes("yaxis"),
155	            )
156	          ) {
157	            // Axis changes are keypath updates, so need to use lodash.set
158	            // e.g. xaxis.range[0], xaxis.range[1], yaxis.range[0], yaxis.range[1]
159	            const obj: Partial<Plotly.Layout> = {};
160	            Object.entries(layoutUpdate).forEach(([key, value]) => {
161	              set(obj, key, value);
162	            });
163	            setValue((prev) => ({ ...prev, ...obj }));
164	          }
165	        }}
166	        onDeselect={useEvent(() => {
167	          setValue((prev) => {
168	            return {
169	              ...prev,
170	              selections: Arrays.EMPTY,
171	              points: Arrays.EMPTY,
172	              indices: Arrays.EMPTY,
173	              range: undefined,
174	            };
175	          });
176	        })}
177	        onTreemapClick={useEvent((evt: Readonly<Plotly.PlotMouseEvent>) => {
178	          if (!evt) {
179	            return;
180	          }
181	
182	          setValue((prev) => ({
183	            ...prev,
184	            points: evt.points.map((point) =>
185	              Objects.pick(point, TREE_MAP_DATA_KEYS),
186	            ),
187	          }));
188	        })}
189	        onSunburstClick={useEvent((evt: Readonly<Plotly.PlotMouseEvent>) => {
190	          if (!evt) {
191	            return;
192	          }
193	
194	          setValue((prev) => ({
195	            ...prev,
196	            points: evt.points.map((point) =>
197	              Objects.pick(point, SUNBURST_DATA_KEYS),
198	            ),
199	          }));
200	        })}
201	        config={plotlyConfig}
202	        onClick={useEvent((evt: Readonly<Plotly.PlotMouseEvent>) => {
203	          if (!evt) {
204	            return;
205	          }
206	
207	          const clickSelection = extractClickSelection(evt);
208	          if (!clickSelection) {
209	            return;
210	          }
211	
212	          setValue((prev) => ({ ...prev, ...clickSelection }));
213	        })}
214	        onSelected={useEvent((evt: Readonly<Plotly.PlotSelectionEvent>) => {
215	          if (!evt) {
216	            return;
217	          }
218	
219	          setValue((prev) => ({
220	            ...prev,
221	            selections:
222	              "selections" in evt ? (evt.selections as unknown[]) : [],
223	            points: extractPoints(evt.points),
224	            indices: extractIndices(evt.points),
225	            range: evt.range,
226	          }));
227	        })}
228	        className="w-full"
229	        useResizeHandler={true}
230	        frames={figure.frames ?? undefined}
231	        onError={useEvent((err: Error) => {
232	          Logger.error("PlotlyPlugin: ", err);
233	        })}
234	      />
235	    );
236	  },
237	);
238	PlotlyComponent.displayName = "PlotlyComponent";
