3	import { get } from "lodash-es";
4	import type * as Plotly from "plotly.js";
5	
6	export interface PlotlyTemplateParser {
7	  /**
8	   * Update the parser with a new hover template, if needed.
9	   */
10	  update(newTemplate: string): PlotlyTemplateParser;
11	  /**
12	   * Given a Plotly.PlotDatum, parse the data and return an object with the key-value pairs.
13	   */
14	  parse(data: Plotly.PlotDatum): Record<string, string>;
15	}
16	
17	/**
18	 * Hover template looks something like this:
19	 *   "Origin=%{customdata[1]}<br>Horsepower=%{x}<br>Miles_per_Gallon=%{y}<br>Weight_in_lbs=%{marker.size}<br>Name=%{customdata[0]}<extra></extra>"
20	 *
21	 * We want to parse the keys/selectors to get the values for each data point.
22	 *
23	 * NOTE: This is a very naive implementation.
24	 * It only works for hover templates that have the pattern key=%{selector}.
25	 */
26	export function createParser(hovertemplate: string): PlotlyTemplateParser {
27	  // Regular expression to match the pattern key=%{selector}
28	  // Match any characters except = for the key (non-greedy to avoid capturing previous content)
29	  const regex = /([^<=>]+)=%{([^}]+)}/g;
30	
31	  // Create an object to hold the key-selector pairs
32	  const keySelectorPairs: Record<string, string> = {};
33	
34	  let match: RegExpExecArray | null;
35	
36	  // Use exec to find all occurrences of the pattern and iterate over them
37	  while ((match = regex.exec(hovertemplate)) !== null) {
38	    // match[1] is the key, match[2] is the selector
39	    keySelectorPairs[match[1]] = match[2];
40	  }
41	
42	  return {
43	    update(newTemplate: string): PlotlyTemplateParser {
44	      // If the template hasn't changed, return the same parser
45	      if (newTemplate === hovertemplate) {
46	        return this;
47	      }
48	      return createParser(newTemplate);
49	    },
50	    parse(data: Plotly.PlotDatum) {
51	      return Object.entries(keySelectorPairs).reduce<Record<string, string>>(
52	        (acc, [key, selector]) => {
53	          acc[key] = get(data, selector);
54	          return acc;
55	        },
56	        {},
57	      );
58	    },
59	  };
60	}
