3	import { usePrevious } from "@uidotdev/usehooks";
4	import { dequal as isEqual } from "dequal";
5	import type * as Plotly from "plotly.js";
6	import { useEffect, useState } from "react";
7	import { Objects } from "@/utils/objects";
8	import type { Figure } from "./Plot";
9	
10	/**
11	 * Keys that are preserved across figure updates when set by user interaction.
12	 * These include dragmode and axis settings that users may adjust.
13	 */
14	export const PERSISTED_LAYOUT_KEYS = ["dragmode", "xaxis", "yaxis"] as const;
15	
16	/**
17	 * Keys that are omitted from layout updates unless they changed in the figure.
18	 * This prevents overwriting user interactions like zoom/pan.
19	 */
20	export const LAYOUT_OMIT_KEYS: (keyof Plotly.Layout)[] = [
21	  "autosize",
22	  "dragmode",
23	  "xaxis",
24	  "yaxis",
25	];
26	
27	/**
28	 * Creates the initial layout for a Plotly figure with sensible defaults.
29	 */
30	export function createInitialLayout(figure: Figure): Partial<Plotly.Layout> {
31	  // Enable autosize if width is not specified
32	  const shouldAutoSize = figure.layout.width === undefined;
33	  return {
34	    autosize: shouldAutoSize,
35	    dragmode: "select",
36	    height: 540,
37	    // Prioritize user's config
38	    ...figure.layout,
39	  };
40	}
41	
42	/**
43	 * Computes the updated layout when the figure changes.
44	 * Preserves user-interaction values (dragmode, xaxis, yaxis) while
45	 * taking everything else from the new figure's layout.
46	 */
47	export function computeLayoutOnFigureChange(
48	  nextFigure: Figure,
49	  prevLayout: Partial<Plotly.Layout>,
50	): Partial<Plotly.Layout> {
51	  return {
52	    ...createInitialLayout(nextFigure),
53	    ...Objects.pick(prevLayout, PERSISTED_LAYOUT_KEYS),
54	  };
55	}
56	
57	/**
58	 * Computes which keys to omit from layout updates based on what changed.
59	 * If a key changed in the figure, we should update it even if it's normally omitted.
60	 */
61	export function computeOmitKeys(
62	  currentLayout: Partial<Plotly.Layout>,
63	  previousLayout: Partial<Plotly.Layout>,
64	): Set<keyof Plotly.Layout> {
65	  const omitKeys = new Set<keyof Plotly.Layout>(LAYOUT_OMIT_KEYS);
66	
67	  // If the key was updated externally (e.g. can be specifically passed in the config)
68	  // then we need to update the layout
69	  for (const key of omitKeys) {
70	    if (!isEqual(currentLayout[key], previousLayout[key])) {
71	      omitKeys.delete(key);
72	    }
73	  }
74	
75	  return omitKeys;
76	}
77	
78	/**
79	 * Computes the layout update when figure.layout changes.
80	 * Omits keys that shouldn't override user interactions unless they changed.
81	 */
82	export function computeLayoutUpdate(
83	  figureLayout: Partial<Plotly.Layout>,
84	  previousFigureLayout: Partial<Plotly.Layout>,
85	  prevLayout: Partial<Plotly.Layout>,
86	): Partial<Plotly.Layout> {
87	  const omitKeys = computeOmitKeys(figureLayout, previousFigureLayout);
88	  const layoutUpdate = Objects.omit(figureLayout, omitKeys);
89	  return { ...prevLayout, ...layoutUpdate };
90	}
91	
92	interface UsePlotlyLayoutOptions {
93	  originalFigure: Figure;
94	  initialValue?: Partial<Plotly.Layout>;
95	  isScriptLoaded?: boolean;
96	}
97	
98	interface UsePlotlyLayoutResult {
99	  figure: Figure;
100	  layout: Partial<Plotly.Layout>;
101	  setLayout: React.Dispatch<React.SetStateAction<Partial<Plotly.Layout>>>;
102	  handleReset: () => void;
103	}
104	
105	/**
106	 * Hook that manages the Plotly figure and layout state.
107	 *
108	 * This hook handles:
109	 * - Cloning the figure to prevent Plotly mutations
110	 * - Managing layout state with proper preservation of user interactions
111	 * - Syncing layout when the figure changes
112	 * - Providing a reset function to restore original state
113	 */
114	export function usePlotlyLayout({
115	  originalFigure,
116	  initialValue,
117	  isScriptLoaded = true,
118	}: UsePlotlyLayoutOptions): UsePlotlyLayoutResult {
119	  const [figure, setFigure] = useState(() => {
120	    // We clone the figure since Plotly mutates the figure in place
121	    return structuredClone(originalFigure);
122	  });
123	
124	  const [layout, setLayout] = useState<Partial<Plotly.Layout>>(() => {
125	    return {
126	      ...createInitialLayout(figure),
127	      // Override with persisted values (dragmode, xaxis, yaxis)
128	      ...initialValue,
129	    };
130	  });
131	
132	  // Update figure and layout when originalFigure changes
133	  useEffect(() => {
134	    const nextFigure = structuredClone(originalFigure);
135	    setFigure(nextFigure);
136	    // Start with the new figure's layout, then only preserve user-interaction
137	    // values (dragmode, xaxis, yaxis) from the previous layout.
138	    // We don't want to preserve other properties like `shapes` from the previous
139	    // layout, as they should be fully controlled by the figure prop.
140	    setLayout((prev) => computeLayoutOnFigureChange(nextFigure, prev));
141	  }, [originalFigure, isScriptLoaded]);
142	
143	  const prevFigure = usePrevious(figure) ?? figure;
144	
145	  // Sync layout when figure.layout changes
146	  useEffect(() => {
147	    setLayout((prev) =>
148	      computeLayoutUpdate(figure.layout, prevFigure.layout, prev),
149	    );
150	  }, [figure.layout, prevFigure.layout]);
151	
152	  const handleReset = () => {
153	    const nextFigure = structuredClone(originalFigure);
154	    setFigure(nextFigure);
155	    setLayout(createInitialLayout(nextFigure));
156	  };
157	
158	  return {
159	    figure,
160	    layout,
161	    setLayout,
162	    handleReset,
163	  };
164	}
