def _to_numeric_coord(value: Any) -> "float | int":
    """Convert a coordinate value to a numeric value for range comparisons.

    Handles numeric values, ISO datetime strings, and datetime/date objects.
    Naive datetime objects are treated as UTC so that they produce the same
    numeric value as a UTC ISO datetime string and a UTC-aware datetime,
    regardless of the system timezone.
    """
    import datetime

    # Booleans are ints in Python; keep them as-is (numeric).
    if isinstance(value, (int, float)):
        return value

    if isinstance(value, str):
        try:
            value = datetime.datetime.fromisoformat(value.replace("Z", "+00:00"))
        except (ValueError, AttributeError):
            return value

    if isinstance(value, datetime.datetime):
        if value.tzinfo is None:
            # Treat naive datetimes as UTC for a timezone-independent result.
            value = value.replace(tzinfo=datetime.timezone.utc)
        return value.timestamp()

    if isinstance(value, datetime.date):
        dt = datetime.datetime(
            value.year,
            value.month,
            value.day,
            tzinfo=datetime.timezone.utc,
        )
        return dt.timestamp()

    return value


def _bar_value_in_selection_range(
    trace: Any,
    point_idx: int,
    point_value: Any,
    selection_min: Any,
    selection_max: Any,
) -> bool:
    """Check whether a bar's value extent overlaps the selection range.

    A bar spans from its base (default 0) to base + value along the value
    axis. It is considered selected when that extent overlaps the selection
    range on the value axis.

    Returns False (never raises) when the bar value or the trace base are
    non-numeric (e.g. string) values.
    """
    base_raw = getattr(trace, "base", None)
    if base_raw is None:
        base_value: Any = 0
    else:
        base_value = _get_indexed_value(base_raw, point_idx)
        if base_value is None:
            base_value = 0

    try:
        value = float(point_value)
        base = float(base_value)
        sel_min = float(selection_min)
        sel_max = float(selection_max)
    except (TypeError, ValueError):
        return False

    bar_low = min(base, base + value)
    bar_high = max(base, base + value)
    lo = min(sel_min, sel_max)
    hi = max(sel_min, sel_max)

    return bar_low <= hi and bar_high >= lo


