import { pick } from "lodash-es";
import type * as Plotly from "plotly.js";
import { createParser, type PlotlyTemplateParser } from "./parse-from-template";

type AxisName = string;
type AxisDatum = unknown;

export interface PlotlyClickSelection {
  points: Record<AxisName, AxisDatum>[] | Plotly.PlotDatum[];
  indices: number[];
  range: undefined;
  selections: unknown[];
}

/**
 * A mode bar button is either a built-in button referenced by name (string) or
 * a custom button object with a name, title, icon, and click handler.
 */
export type ModeBarButton =
  | string
  | {
      name: string;
      title: string;
      icon: object;
      click: (gd: Plotly.PlotlyHTMLElement, ev: MouseEvent) => void;
    };

const SCATTER_TRACE_TYPES = new Set(["scatter", "scattergl"]);

const STANDARD_POINT_KEYS: string[] = [
  "x",
  "y",
  "z",
  "lat",
  "lon",
  "curveNumber",
  "pointNumber",
  "pointNumbers",
  "pointIndex",
] as const;

/**
 * Returns true if any trace is a pure line trace: a scatter/scattergl trace
 * whose mode includes "lines" but not "markers".
 */
export function hasPureLineTrace(traces: Plotly.Data[]): boolean {
  if (!traces) {
    return false;
  }
  return traces.some((trace) => {
    const type = (trace as { type?: string }).type;
    if (type !== "scatter" && type !== "scattergl") {
      return false;
    }
    const mode = (trace as { mode?: string }).mode;
    return (
      typeof mode === "string" &&
      mode.includes("lines") &&
      !mode.includes("markers")
    );
  });
}

/**
 * Returns the two custom mode bar buttons used to trigger box/lasso selection
 * on line charts, wired to the provided `setDragmode` callback.
 */
export function lineSelectionButtons(
  setDragmode: (mode: string) => void,
): ModeBarButton[] {
  return [
    {
      name: "line-box-select",
      title: "Box select",
      icon: {
        width: 1000,
        height: 1000,
        path: "M0 0h1000v1000H0z",
      },
      click: () => setDragmode("select"),
    },
    {
      name: "line-lasso-select",
      title: "Lasso select",
      icon: {
        width: 1031,
        height: 1000,
        path: "M0 0h1031v1000H0z",
      },
      click: () => setDragmode("lasso"),
    },
  ];
}

/**
 * Merges two arrays of mode bar buttons, deduplicating string buttons (first
 * occurrence wins) while always preserving custom object buttons.
 */
export function mergeModeBarButtonsToAdd(
  existing: ModeBarButton[],
  add: ModeBarButton[],
): ModeBarButton[] {
  const result: ModeBarButton[] = [];
  const seenStrings = new Set<string>();

  for (const button of [...(existing ?? []), ...(add ?? [])]) {
    if (typeof button === "string") {
      if (seenStrings.has(button)) {
        continue;
      }
      seenStrings.add(button);
      result.push(button);
    } else {
      result.push(button);
    }
  }

  return result;
}

/**
 * Returns true when the clicked points belong to trace types that support
 * direct click selection: bar, heatmap, histogram, or scatter/scattergl traces
 * without an explicit mode. Returns false when all scatter/scattergl points
 * have an explicit mode (e.g. "markers"), since those are handled via
 * box/lasso selection instead.
 */
export function shouldHandleClickSelection(
  points: Plotly.PlotDatum[],
): boolean {
  if (!points || points.length === 0) {
    return false;
  }

  return points.some((point) => {
    const type = point.data?.type;
    if (type === "bar" || type === "heatmap" || type === "histogram") {
      return true;
    }
    if (typeof type === "string" && SCATTER_TRACE_TYPES.has(type)) {
      const mode = (point.data as { mode?: string } | undefined)?.mode;
      // Only scatter/scattergl traces without an explicit mode are
      // click-selectable; explicit modes (markers, lines, ...) use box/lasso.
      return mode == null;
    }
    return false;
  });
}

function getPointIndex(point: Plotly.PlotDatum): number | undefined {
  if (typeof point.pointIndex === "number") {
    return point.pointIndex;
  }

  if (typeof point.pointNumber === "number") {
    return point.pointNumber;
  }

  return undefined;
}

/**
 * Extracts a flat list of point indices. Prefers pointIndex, then pointNumber,
 * and finally the finite values within the pointNumbers array (NaN and
 * non-finite values are excluded).
 */
export function extractIndices(points: Plotly.PlotDatum[]): number[] {
  return points.flatMap((point) => {
    const index = getPointIndex(point);
    if (typeof index === "number") {
      return [index];
    }

    const pointNumbers = (point as { pointNumbers?: unknown }).pointNumbers;
    if (Array.isArray(pointNumbers)) {
      return pointNumbers.filter(
        (value): value is number =>
          typeof value === "number" && Number.isFinite(value),
      );
    }

    return [];
  });
}

/**
 * This is a hack to extract the points with their original keys,
 * instead of the ones that Plotly uses internally,
 * by using the hovertemplate.
 *
 * For scatter line traces, the clicked point does not correspond to a data
 * vertex, so x/y are inferred from the trace's fullData arrays using
 * pointNumber as the index. For heatmap traces, only x/y/z are returned.
 */
export function extractPoints(
  points: Plotly.PlotDatum[],
): Record<AxisName, AxisDatum>[] {
  if (!points) {
    return [];
  }

  let parser: PlotlyTemplateParser | undefined;

  return points.map((point) => {
    // For heatmaps, return only the standard x/y/z fields.
    if (point.data?.type === "heatmap") {
      return pick(point, ["x", "y", "z"]);
    }

    const standardPointFields = pick(point, STANDARD_POINT_KEYS);

    // Infer coordinates from fullData arrays for scatter line traces.
    const fullData = (point as { fullData?: unknown }).fullData as
      | { mode?: string; x?: unknown[]; y?: unknown[] }
      | undefined;
    const isLineTrace =
      typeof fullData?.mode === "string" && fullData.mode.includes("lines");

    let inferredFields: Record<string, unknown> = {};
    if (isLineTrace && typeof point.pointNumber === "number") {
      const idx = point.pointNumber;
      const xArr = fullData?.x;
      const yArr = fullData?.y;
      inferredFields = {
        x: Array.isArray(xArr) ? xArr[idx] : point.x,
        y: Array.isArray(yArr) ? yArr[idx] : point.y,
        pointNumber: idx,
        pointIndex: idx,
      };
    }

    // Get the first hovertemplate
    const hovertemplate = Array.isArray(point.data.hovertemplate)
      ? point.data.hovertemplate[0]
      : point.data.hovertemplate;

    // When there's no hovertemplate, pick keys directly from the point,
    // retaining any inferred coordinate fields.
    if (!hovertemplate) {
      return { ...standardPointFields, ...inferredFields };
    }

    // Update or create a parser
    parser = parser
      ? parser.update(hovertemplate)
      : createParser(hovertemplate);
    // Inferred coordinate fields take precedence over parsed values so the
    // data vertex coordinates are retained.
    return {
      ...standardPointFields,
      ...parser.parse(point),
      ...inferredFields,
    };
  });
}
